import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.C0KMm31j.js";const o="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_09_01_sdk.png",c="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_09_02_appserver.png",n="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_09_03_agents_sdk.png",l="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_09_04_collaboration.png",s="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_09_05_guardrails.png",p="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_09_06_decision.png",x=JSON.parse('{"title":"把 Codex 装进你的产品：SDK、App Server、Slack 与 Linear 全链路","description":"当 Codex 从个人终端进入内部平台、GitHub、Slack 或 Linear，外层系统必须承担身份、租户、业务状态、幂等、审计和回写责任。集成不是把 CLI 输出搬进网页，而是选择与产品需求匹配的程序化接口。","frontmatter":{"title":"把 Codex 装进你的产品：SDK、App Server、Slack 与 Linear 全链路","description":"当 Codex 从个人终端进入内部平台、GitHub、Slack 或 Linear，外层系统必须承担身份、租户、业务状态、幂等、审计和回写责任。集成不是把 CLI 输出搬进网页，而是选择与产品需求匹配的程序化接口。","date":"2026-08-10","topic":"AI 底层学习","section":"OpenAI官方文档解读","readingTime":4,"source":"2026-08-10/ai_codex_official_09_sdk_integrations.md","status":"archived","cover":"/article-assets/2026-08-10/ai_codex_official_09_01_sdk.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/ai/openai-codex-complete-guide"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"把 Codex 装进你的产品：SDK、App Server、Slack 与 Linear 全链路"}],["meta",{"property":"og:description","content":"当 Codex 从个人终端进入内部平台、GitHub、Slack 或 Linear，外层系统必须承担身份、租户、业务状态、幂等、审计和回写责任。集成不是把 CLI 输出搬进网页，而是选择与产品需求匹配的程序化接口。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/ai/openai-codex-complete-guide"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_09_01_sdk.png"}],["meta",{"property":"article:published_time","content":"2026-08-10"}],["meta",{"name":"twitter:title","content":"把 Codex 装进你的产品：SDK、App Server、Slack 与 Linear 全链路"}],["meta",{"name":"twitter:description","content":"当 Codex 从个人终端进入内部平台、GitHub、Slack 或 Linear，外层系统必须承担身份、租户、业务状态、幂等、审计和回写责任。集成不是把 CLI 输出搬进网页，而是选择与产品需求匹配的程序化接口。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_09_01_sdk.png"}],["meta",{"name":"robots","content":"noindex,follow"}]],"search":false,"prev":false,"next":false},"headers":[],"relativePath":"archive/ai-codex-official-09-sdk-integrations.md","filePath":"archive/ai-codex-official-09-sdk-integrations.md","lastUpdated":null}'),d={name:"archive/ai-codex-official-09-sdk-integrations.md"};function h(_,e,m,k,f,S){return t(),r("div",null,[...e[0]||(e[0]=[i('<blockquote><p>本文为历史归档版本，不再更新。请阅读<a href="/Nav2ArticlesSite/ai/openai-codex-complete-guide">当前版本</a>。</p></blockquote><h1 id="把-codex-装进你的产品-sdk、app-server、slack-与-linear-全链路" tabindex="-1">把 Codex 装进你的产品：SDK、App Server、Slack 与 Linear 全链路 <a class="header-anchor" href="#把-codex-装进你的产品-sdk、app-server、slack-与-linear-全链路" aria-label="Permalink to &quot;把 Codex 装进你的产品：SDK、App Server、Slack 与 Linear 全链路&quot;">​</a></h1><p>当 Codex 从个人终端进入内部平台、GitHub、Slack 或 Linear，外层系统必须承担身份、租户、业务状态、幂等、审计和回写责任。集成不是把 CLI 输出搬进网页，而是选择与产品需求匹配的程序化接口。</p><h2 id="一、sdk-适合程序化-agent-工作流" tabindex="-1">一、SDK 适合程序化 Agent 工作流 <a class="header-anchor" href="#一、sdk-适合程序化-agent-工作流" aria-label="Permalink to &quot;一、SDK 适合程序化 Agent 工作流&quot;">​</a></h2><h3 id="_1-1-应用拥有业务状态" tabindex="-1">1.1 应用拥有业务状态 <a class="header-anchor" href="#_1-1-应用拥有业务状态" aria-label="Permalink to &quot;1.1 应用拥有业务状态&quot;">​</a></h3><p>用户、工单、租户、重试和审批状态应保存在应用数据库。Codex Thread 负责代理上下文，不应成为唯一业务事实源。</p><h3 id="_1-2-thread-保留连续任务上下文" tabindex="-1">1.2 Thread 保留连续任务上下文 <a class="header-anchor" href="#_1-2-thread-保留连续任务上下文" aria-label="Permalink to &quot;1.2 Thread 保留连续任务上下文&quot;">​</a></h3><p>应用可以启动运行、继续同一 Thread，并消费事件或最终结果。Thread 标识必须与业务对象和访问主体正确关联。</p><h3 id="_1-3-结构化输出降低集成脆弱性" tabindex="-1">1.3 结构化输出降低集成脆弱性 <a class="header-anchor" href="#_1-3-结构化输出降低集成脆弱性" aria-label="Permalink to &quot;1.3 结构化输出降低集成脆弱性&quot;">​</a></h3><p>机器需要稳定 Schema、错误分类和产物位置。自然语言总结可以展示给人，但不能成为关键权限或发布决策的唯一解析来源。</p><p><img src="'+o+'" alt="图 1：应用请求经过 Thread、Agent 运行与结构化结果返回"></p><h2 id="二、app-server-适合丰富客户端" tabindex="-1">二、App Server 适合丰富客户端 <a class="header-anchor" href="#二、app-server-适合丰富客户端" aria-label="Permalink to &quot;二、App Server 适合丰富客户端&quot;">​</a></h2><h3 id="_2-1-它管理完整交互生命周期" tabindex="-1">2.1 它管理完整交互生命周期 <a class="header-anchor" href="#_2-1-它管理完整交互生命周期" aria-label="Permalink to &quot;2.1 它管理完整交互生命周期&quot;">​</a></h3><p>App Server 提供认证、线程、回合、工具事件、历史、审批和流式通知，适合构建桌面端、IDE 或内部工作台。</p><h3 id="_2-2-协议以当前版本-schema-为准" tabindex="-1">2.2 协议以当前版本 Schema 为准 <a class="header-anchor" href="#_2-2-协议以当前版本-schema-为准" aria-label="Permalink to &quot;2.2 协议以当前版本 Schema 为准&quot;">​</a></h3><p>客户端应从运行版本生成 TypeScript 或 JSON Schema，不长期复制文章中的示例。实验传输和字段可能变化，必须建立版本兼容策略。</p><h3 id="_2-3-远程连接需要安全传输与认证" tabindex="-1">2.3 远程连接需要安全传输与认证 <a class="header-anchor" href="#_2-3-远程连接需要安全传输与认证" aria-label="Permalink to &quot;2.3 远程连接需要安全传输与认证&quot;">​</a></h3><p>本机 stdio、Unix Socket 与远程 WebSocket 的风险不同。非本机连接需要 TLS、能力令牌或签名令牌，并避免在命令行暴露秘密。</p><p><img src="'+c+'" alt="图 2：客户端通过 App Server 管理会话、事件与审批"></p><h2 id="三、agents-sdk-可以把-codex-当专业工具" tabindex="-1">三、Agents SDK 可以把 Codex 当专业工具 <a class="header-anchor" href="#三、agents-sdk-可以把-codex-当专业工具" aria-label="Permalink to &quot;三、Agents SDK 可以把 Codex 当专业工具&quot;">​</a></h2><p>更大的 Agent 系统可以通过 MCP Server 调用 Codex。上游 Agent 负责业务编排，Codex 在受控工作区完成代码任务并返回结果。外层仍要限制工作目录、权限、超时和输出去向。</p><p>MCP 只提供调用协议，不能自动继承业务用户权限。上游自然语言同样属于不可信输入，不能绕过 Codex 的沙箱和审批。</p><p><img src="'+n+'" alt="图 3：Agents SDK 通过 MCP 调用隔离的 Codex 编码执行器"></p><h2 id="四、slack-与-linear-是协作入口" tabindex="-1">四、Slack 与 Linear 是协作入口 <a class="header-anchor" href="#四、slack-与-linear-是协作入口" aria-label="Permalink to &quot;四、Slack 与 Linear 是协作入口&quot;">​</a></h2><h3 id="_4-1-消息与工单需要转成执行合同" tabindex="-1">4.1 消息与工单需要转成执行合同 <a class="header-anchor" href="#_4-1-消息与工单需要转成执行合同" aria-label="Permalink to &quot;4.1 消息与工单需要转成执行合同&quot;">​</a></h3><p>一句“修一下上面的问题”可能缺少仓库、版本、范围和验收条件。触发前应补齐目标与上下文，长线程需要在最新消息重述关键事实。</p><h3 id="_4-2-环境与仓库选择必须可见" tabindex="-1">4.2 环境与仓库选择必须可见 <a class="header-anchor" href="#_4-2-环境与仓库选择必须可见" aria-label="Permalink to &quot;4.2 环境与仓库选择必须可见&quot;">​</a></h3><p>集成会在用户可访问环境中匹配仓库，歧义时可能使用最近环境。高价值任务应显式指定目标，并在结果中记录实际执行位置。</p><h3 id="_4-3-回复结果不等于允许合并" tabindex="-1">4.3 回复结果不等于允许合并 <a class="header-anchor" href="#_4-3-回复结果不等于允许合并" aria-label="Permalink to &quot;4.3 回复结果不等于允许合并&quot;">​</a></h3><p>Slack 或 Linear 中的摘要和任务链接方便协作，但代码仍要进入 Pull Request、Checks 和 Review。协作工具不能替代源代码平台治理。</p><p><img src="'+l+'" alt="图 4：Slack 与 Linear 把协作上下文转成 Cloud 任务"></p><h2 id="五、集成平台必须补齐安全护栏" tabindex="-1">五、集成平台必须补齐安全护栏 <a class="header-anchor" href="#五、集成平台必须补齐安全护栏" aria-label="Permalink to &quot;五、集成平台必须补齐安全护栏&quot;">​</a></h2><h3 id="_5-1-身份映射" tabindex="-1">5.1 身份映射 <a class="header-anchor" href="#_5-1-身份映射" aria-label="Permalink to &quot;5.1 身份映射&quot;">​</a></h3><p>不同系统中的账号要关联到真实责任主体，不能用共享长期 Token 混淆动作来源。</p><h3 id="_5-2-权限分层" tabindex="-1">5.2 权限分层 <a class="header-anchor" href="#_5-2-权限分层" aria-label="Permalink to &quot;5.2 权限分层&quot;">​</a></h3><p>读取工单、访问仓库、写补丁、回复消息和合并代码使用不同权限，并分别接受组织与源系统控制。</p><h3 id="_5-3-幂等回写" tabindex="-1">5.3 幂等回写 <a class="header-anchor" href="#_5-3-幂等回写" aria-label="Permalink to &quot;5.3 幂等回写&quot;">​</a></h3><p>重试不能制造重复评论、分支或任务。应用用稳定业务键关联每次执行。</p><h3 id="_5-4-审计追踪" tabindex="-1">5.4 审计追踪 <a class="header-anchor" href="#_5-4-审计追踪" aria-label="Permalink to &quot;5.4 审计追踪&quot;">​</a></h3><p>请求、Thread、仓库版本、工具事件、批准、验证与外部状态必须能够串联。</p><p><img src="'+s+'" alt="图 5：身份、输入、权限、幂等与审计组成集成护栏"></p><h2 id="六、选择接口看责任而不是功能数量" tabindex="-1">六、选择接口看责任而不是功能数量 <a class="header-anchor" href="#六、选择接口看责任而不是功能数量" aria-label="Permalink to &quot;六、选择接口看责任而不是功能数量&quot;">​</a></h2><p>固定批处理和后端 Job 使用 SDK；需要线程、流式事件和审批界面的客户端使用 App Server；已有 Agent 平台把 Codex 当专业执行器时使用 MCP；团队讨论和工单派发使用 Slack 与 Linear。选择最少承担额外责任的接口，通常比选择“功能最多”的接口更可靠。</p><p><img src="'+p+'" alt="图 6：SDK、App Server、MCP 与协作入口的选择地图"></p><h2 id="七、官方参考资料" tabindex="-1">七、官方参考资料 <a class="header-anchor" href="#七、官方参考资料" aria-label="Permalink to &quot;七、官方参考资料&quot;">​</a></h2><p><a href="https://learn.chatgpt.com/docs/codex-sdk" target="_blank" rel="noreferrer">OpenAI Docs：Codex SDK</a></p><p><a href="https://learn.chatgpt.com/docs/app-server" target="_blank" rel="noreferrer">OpenAI Docs：App Server</a></p><p><a href="https://learn.chatgpt.com/docs/mcp-server" target="_blank" rel="noreferrer">OpenAI Docs：Use Codex with Agents SDK</a></p><p><a href="https://learn.chatgpt.com/docs/third-party/linear" target="_blank" rel="noreferrer">OpenAI Docs：Linear</a></p><p><a href="https://learn.chatgpt.com/docs/third-party/slack" target="_blank" rel="noreferrer">OpenAI Docs：Slack</a></p>',50)])])}const b=a(d,[["render",h]]);export{x as __pageData,b as default};
